<script setup lang="ts">import{ref}from'vue';const emit=defineEmits<{send:[text:string],close:[]}>();const text=ref(''),error=ref('');function send(){if(!text.value.trim()){error.value='请先写下一句祝福';return}emit('send',text.value.trim())}</script>
<template><div class="backdrop" @click.self="emit('close')"><section class="card" role="dialog" aria-modal="true"><button class="close" @click="emit('close')">关闭</button><small>MOONLIGHT MESSAGE</small><h2>把想念，交给月光</h2><p>它会替你抵达遥远的地方。</p><textarea v-model="text" maxlength="56" placeholder="写下你想送给 TA 的一句话……" @input="error=''"/><em v-if="error">{{error}}</em><button class="glow full" @click="send">点亮月光</button></section></div></template>
